    const down = sum(map(d, (x) => Math.max(-x, 0)), len);
    const values = zip(up, down, (u, w) => u + w === 0 ? 0 : 100 * (u - w) / (u + w));
    const bull = str3(inputs, "bullColor", palette.BULLISH);
