var fisher = {
  type: "fisher-transform",
  title: msg("indicator.fisherTransform.title", "Fisher Transform"),
  shortTitle: msg("indicator.fisherTransform.shortTitle", "Fisher"),
  overlay: false,
  inputs: [
    lengthInput(9, "length", msg("indicator.fisherTransform.length", "Length"), 5e3, msg("indicator.fisherTransform.length.tooltip", "Lookback period used to locate the median price hl2 within its highest-lowest range. Ehlers' original length is 10; 9 is the common platform default.")),
    colorInput(palette.NEUTRAL, msg("indicator.fisherTransform.color", "Fisher Line"), "color", msg("indicator.fisherTransform.color.tooltip", "Color of the Fisher line when it sits exactly on its trigger.")),
    colorInput(palette.NEUTRAL, msg("indicator.fisherTransform.triggerColor", "Trigger Line"), "triggerColor", msg("indicator.fisherTransform.triggerColor.tooltip", "Color of the trigger line, the Fisher value delayed one bar.")),
    colorInput(palette.BULLISH, msg("indicator.fisherTransform.bullColor", "Bullish"), "bullColor", msg("indicator.fisherTransform.bullColor.tooltip", "Color of the Fisher line and fill while it is above the trigger.")),
    colorInput(palette.BEARISH, msg("indicator.fisherTransform.bearColor", "Bearish"), "bearColor", msg("indicator.fisherTransform.bearColor.tooltip", "Color of the Fisher line and fill while it is below the trigger."))
  ],
  compute: (bars, inputs) => {
    const len = num3(inputs, "length", 9);
    const hl2 = sourceValues(bars, "HL2");
    const hi = highest(hl2, len);
    const lo = lowest(hl2, len);
    const n = bars.length;
    const out = new Array(n).fill(Number.NaN);
    let position = 0;
    let value = 0;
    for (let i = 0; i < n; i++) {
      const h = hi[i];
      const l = lo[i];
      if (!Number.isFinite(h) || !Number.isFinite(l)) continue;
      const raw = h > l ? (hl2[i] - l) / (h - l) - 0.5 : 0;
      position = 0.66 * raw + 0.67 * position;
      position = position > 0.99 ? 0.999 : position < -0.99 ? -0.999 : position;
      value = 0.5 * Math.log((1 + position) / (1 - position)) + 0.5 * value;
      out[i] = value;
    }
    const trigger = shift(out, 1);
    const neutral = str3(inputs, "color", palette.NEUTRAL);
    const bull = str3(inputs, "bullColor", palette.BULLISH);
    const bear = str3(inputs, "bearColor", palette.BEARISH);
    const inkOf = (i) => {
      const f = out[i];
      const t33 = trigger[i];
      if (!Number.isFinite(t33)) return neutral;
      return f > t33 ? bull : f < t33 ? bear : neutral;
    };
    return {
      plots: [
        { key: "fisher", title: msg("indicator.fisherTransform.plot.fisher", "Fisher"), values: out, color: neutral, width: 2, colors: out.map((x, i) => Number.isFinite(x) ? inkOf(i) : null) },
        { key: "trigger", title: msg("indicator.fisherTransform.plot.trigger", "Trigger"), values: trigger, color: str3(inputs, "triggerColor", palette.NEUTRAL) }
      ],
      bands: [{ key: "spread", from: "fisher", to: "trigger", color: transp(neutral, 80), colors: out.map((x, i) => Number.isFinite(x) ? transp(inkOf(i), 80) : null) }],
      levels: [
        { key: "upper", price: 1.5, color: palette.NEUTRAL, lineStyle: "dashed", title: msg("indicator.fisherTransform.level.upper", "Upper Level") },
        { key: "lower", price: -1.5, color: palette.NEUTRAL, lineStyle: "dashed", title: msg("indicator.fisherTransform.level.lower", "Lower Level") },
        { key: "zero", price: 0, color: palette.NEUTRAL, lineStyle: "dotted", title: msg("indicator.fisherTransform.level.zero", "Zero Line") }
      ]
    };
  }
};
