var adx = {
  type: "average-directional-index",
  title: msg("indicator.averageDirectionalIndex.title", "Average Directional Index"),
  shortTitle: msg("indicator.averageDirectionalIndex.shortTitle", "ADX"),
  overlay: false,
  inputs: [
    lengthInput(14, "diLength", msg("indicator.averageDirectionalIndex.diLength", "DI Length"), 5e3, msg("indicator.averageDirectionalIndex.diLength.tooltip", "Wilder RMA smoothing length applied to directional movement and true range when computing +DI and −DI.")),
    lengthInput(14, "adxLength", msg("indicator.averageDirectionalIndex.adxLength", "ADX Smoothing"), 5e3, msg("indicator.averageDirectionalIndex.adxLength.tooltip", "Wilder RMA smoothing length applied to DX to obtain the ADX line.")),
    floatInput("keyLevel", msg("indicator.averageDirectionalIndex.keyLevel", "Key Level"), 25, 0, 100, 1, msg("indicator.averageDirectionalIndex.keyLevel.tooltip", "Trend strength reference level; ADX above it is commonly read as a trending market.")),
    colorInput(palette.BULLISH, msg("indicator.averageDirectionalIndex.plusDiColor", "+DI Color"), "plusDiColor", msg("indicator.averageDirectionalIndex.plusDiColor.tooltip", "Color of the plus directional indicator, and of the ADX line above the key level while +DI leads.")),
    colorInput(palette.BEARISH, msg("indicator.averageDirectionalIndex.minusDiColor", "−DI Color"), "minusDiColor", msg("indicator.averageDirectionalIndex.minusDiColor.tooltip", "Color of the minus directional indicator, and of the ADX line above the key level while −DI leads.")),
    colorInput(palette.NEUTRAL, msg("indicator.averageDirectionalIndex.adxColor", "ADX Color"), "adxColor", msg("indicator.averageDirectionalIndex.adxColor.tooltip", "Color of the ADX line while it sits below the key level — no trend strong enough to trade."))
  ],
  compute: (bars, inputs) => {
    const diLen = num3(inputs, "diLength", 14);
    const n = bars.length;
    const plusDm = new Array(n).fill(Number.NaN);
    const minusDm = new Array(n).fill(Number.NaN);
    for (let i = 1; i < n; i++) {
      const up = bars[i].high - bars[i - 1].high;
      const dn = bars[i - 1].low - bars[i].low;
      plusDm[i] = up > dn && up > 0 ? up : 0;
      minusDm[i] = dn > up && dn > 0 ? dn : 0;
    }
    const atrLine = rma(trueRange(bars), diLen);
    const plusDi = zip(rma(plusDm, diLen), atrLine, (d, a) => a === 0 ? 0 : 100 * d / a);
    const minusDi = zip(rma(minusDm, diLen), atrLine, (d, a) => a === 0 ? 0 : 100 * d / a);
    const dx = zip(plusDi, minusDi, (p, m) => p + m === 0 ? 0 : 100 * Math.abs(p - m) / (p + m));
    const adxLine = rma(dx, num3(inputs, "adxLength", 14));
    const plusInk = str3(inputs, "plusDiColor", palette.BULLISH);
    const minusInk = str3(inputs, "minusDiColor", palette.BEARISH);
    const neutralInk = str3(inputs, "adxColor", palette.NEUTRAL);
    const keyLevel = num3(inputs, "keyLevel", 25);
    const adxColors = adxLine.map((x, i) => {
      if (!Number.isFinite(x)) return null;
      if (x <= keyLevel) return neutralInk;
      return (plusDi[i] ?? 0) > (minusDi[i] ?? 0) ? plusInk : minusInk;
    });
    return {
      plots: [
        { key: "plusDi", title: msg("indicator.averageDirectionalIndex.plot.plusDi", "+DI"), values: plusDi, color: transp(plusInk, 30) },
        { key: "minusDi", title: "-DI", displayTitle: msg("indicator.averageDirectionalIndex.plot.minusDi", "−DI"), values: minusDi, color: transp(minusInk, 30) },
        { key: "adx", title: msg("indicator.averageDirectionalIndex.plot.adx", "ADX"), values: adxLine, color: neutralInk, width: 2, colors: adxColors }
      ],
      levels: [{ key: "keyLevel", price: keyLevel, color: palette.NEUTRAL, lineStyle: "dashed", title: msg("indicator.averageDirectionalIndex.level.keyLevel", "Key Level") }]
    };
  }
};
