var CHOP_TREND_LENGTH = 34;
var CHOP_RANGE_LENGTH = 30;
var CHOP_SPAN = 25;
var CHOP_ZONE_EDGES = [0.71, 2.14, 3.57, 5];
function chopZone(angle) {
  const steepness = Math.abs(angle);
  let zone = 0;
  for (const edge of CHOP_ZONE_EDGES) if (steepness >= edge) zone += 1;
  return angle < 0 ? -zone : zone;
}
var chopZoneSpec = {
  type: "chop-zone",
  title: msg("indicator.chopZone.title", "Chop Zone"),
  overlay: false,
  inputs: [
    colorInput(palette.BULLISH, msg("indicator.chopZone.bullColor", "Rising"), "bullColor", msg("indicator.chopZone.bullColor.tooltip", "Color of the steepest rising zone. The three gentler rising zones blend from the flat color toward it.")),
    colorInput(palette.BEARISH, msg("indicator.chopZone.bearColor", "Falling"), "bearColor", msg("indicator.chopZone.bearColor.tooltip", "Color of the steepest falling zone. The three gentler falling zones blend from the flat color toward it.")),
    colorInput(palette.WARNING, msg("indicator.chopZone.flatColor", "Flat"), "flatColor", msg("indicator.chopZone.flatColor.tooltip", "Color of the bars where the trend line is flat: a choppy market."))
  ],
  compute: (bars, inputs) => {
    const trend = ema(closes(bars), CHOP_TREND_LENGTH);
    const top = highest(highs(bars), CHOP_RANGE_LENGTH);
    const bottom = lowest(highs(bars), CHOP_RANGE_LENGTH);
    const bull = str3(inputs, "bullColor", palette.BULLISH);
    const bear = str3(inputs, "bearColor", palette.BEARISH);
    const flat = str3(inputs, "flatColor", palette.WARNING);
    const steepest = CHOP_ZONE_EDGES.length;
    const values = new Array(bars.length).fill(Number.NaN);
    const colors = new Array(bars.length).fill(null);
    for (let i = 1; i < bars.length; i++) {
      const now2 = trend[i];
      const before = trend[i - 1];
      const high = top[i];
      const low = bottom[i];
      if (!Number.isFinite(now2) || !Number.isFinite(before) || !Number.isFinite(high) || !Number.isFinite(low)) continue;
      const b = bars[i];
      const typical = (b.high + b.low + b.close) / 3;
      const range = high - low;
      const rise = range > 0 && typical !== 0 ? (now2 - before) / typical * (CHOP_SPAN / range * low) : 0;
      const degrees = Math.round(Math.atan(Math.abs(rise)) * 180 / Math.PI);
      const zone = chopZone(rise < 0 ? -degrees : degrees);
      values[i] = 1;
      colors[i] = zone === 0 ? flat : gradient(Math.abs(zone), 0, steepest, flat, zone > 0 ? bull : bear);
    }
    return { plots: [{ key: "zone", title: msg("indicator.chopZone.plot.zone", "Chop Zone"), values, kind: "columns", color: flat, colors, base: 0 }] };
  }
};
