var klinger = {
  type: "klinger-oscillator",
  title: msg("indicator.klingerOscillator.title", "Klinger Oscillator"),
  shortTitle: msg("indicator.klingerOscillator.shortTitle", "KVO"),
  overlay: false,
  inputs: [
    lengthInput(34, "fastLength", msg("indicator.klingerOscillator.fastLength", "Fast Length"), 5e3, msg("indicator.klingerOscillator.fastLength.tooltip", "Length of the fast EMA applied to the volume force.")),
    lengthInput(55, "slowLength", msg("indicator.klingerOscillator.slowLength", "Slow Length"), 5e3, msg("indicator.klingerOscillator.slowLength.tooltip", "Length of the slow EMA applied to the volume force.")),
    lengthInput(13, "signalLength", msg("indicator.klingerOscillator.signalLength", "Signal Length"), 500, msg("indicator.klingerOscillator.signalLength.tooltip", "Length of the EMA applied to the oscillator to obtain the signal line.")),
    colorInput(palette.BULLISH, msg("indicator.klingerOscillator.color", "Bullish"), "color", msg("indicator.klingerOscillator.color.tooltip", "Color of the Klinger oscillator while above zero.")),
    colorInput(palette.BEARISH, msg("indicator.klingerOscillator.bearColor", "Bearish"), "bearColor", msg("indicator.klingerOscillator.bearColor.tooltip", "Color of the Klinger oscillator while below zero.")),
    colorInput(palette.WARNING, msg("indicator.klingerOscillator.signalColor", "Signal"), "signalColor", msg("indicator.klingerOscillator.signalColor.tooltip", "Color of the signal line."))
  ],
  compute: (bars, inputs) => {
    const n = bars.length;
    const force = new Array(n).fill(Number.NaN);
    let trend = 1;
    let prevTrend = 1;
    let cm = 0;
    let prevDm = 0;
    for (let i = 0; i < n; i++) {
      const b = bars[i];
      const hlc = b.high + b.low + b.close;
      const prevHlc = i > 0 ? bars[i - 1].high + bars[i - 1].low + bars[i - 1].close : hlc;
      trend = hlc > prevHlc ? 1 : -1;
      const dm = b.high - b.low;
      cm = i > 0 && trend === prevTrend ? cm + dm : prevDm + dm;
      const v = b.volume;
      force[i] = v == null || !Number.isFinite(v) ? Number.NaN : cm === 0 ? 0 : v * Math.abs(2 * (dm / cm) - 1) * trend * 100;
      prevTrend = trend;
      prevDm = dm;
    }
    const line = sub(ema(force, num3(inputs, "fastLength", 34)), ema(force, num3(inputs, "slowLength", 55)));
    const bull = str3(inputs, "color", palette.BULLISH);
    return centeredOscillator({
      key: "kvo",
      title: msg("indicator.klingerOscillator.plot.kvo", "KVO"),
      values: line,
      ink: { bull, bear: str3(inputs, "bearColor", palette.BEARISH), neutral: bull },
      zeroInk: transp(palette.NEUTRAL, 50),
      valueTransparency: 60,
      extraPlots: [{ key: "signal", title: msg("indicator.klingerOscillator.plot.signal", "Signal"), values: ema(line, num3(inputs, "signalLength", 13)), color: str3(inputs, "signalColor", palette.WARNING) }]
    });
  }
};
